import abc
import re
import xml.etree.ElementTree as ET

from storable import retrieve

from taf.ul.bts_kpi_report_generator.Exception import KPIFailFormatXML
from taf.ul.bts_kpi_report_generator.parser.PMMeasurement import PMMeasurement


class ParserInterface(object):
    __metaclass__ = abc.ABCMeta

    def __init__(self, path_file, counters_need):
        """

        :param path_file:
        :param counters_need:
        """
        self._path_file = path_file
        self._counters_need = counters_need
        self._measurements_file = {}

    @abc.abstractmethod
    def parse(self):
        pass

    @abc.abstractmethod
    def __add_parameters(self, *args):
        pass

    @property
    def measurements_file(self):
        """

        :return:
        """
        return self._measurements_file


class XMLParser(ParserInterface):
    def __init__(self, path_file, counters_need):
        """

        :param path_file:
        :param counters_need:
        """
        super(XMLParser, self).__init__(path_file, counters_need)

    def parse(self):
        """

        :return:
        """
        file_xml = ET.parse(self._path_file)
        file_parse = file_xml.getroot()
        for PMSetup in file_parse:
            if PMSetup.attrib.get('startTime') in self._measurements_file:
                self._ParserInterface__add_parameters(PMSetup)
            elif PMSetup.attrib.get('interval') != '5':
                self._measurements_file[PMSetup.attrib.get('startTime')] = PMMeasurement(
                    PMSetup.attrib.get('startTime'), PMSetup.attrib.get('interval'))
                self._ParserInterface__add_parameters(PMSetup)

    def _ParserInterface__add_parameters(self, pmsetup):
        """

        :param pmsetup:
        :return:
        """
        for pmmoresult in pmsetup:
            dn = self.__return_dn(pmmoresult)

            for m_parameters in pmmoresult.find('NE-WBTS_1.0'):
                if self._counters_need == 'all' or m_parameters.tag in self._counters_need:
                    self._measurements_file[pmsetup.attrib.get('startTime')].add_counter_to_measurement_type(
                        pmmoresult.find('NE-WBTS_1.0').get('measurementType'), m_parameters.tag)
                    self._measurements_file[pmsetup.attrib.get('startTime')]. \
                        add_parameters_pmmeasurement(m_parameters.tag, m_parameters.text, dn)

    @staticmethod
    def __return_dn(pmmoresult):
        """

        :param pmmoresult:
        :return:
        """
        if len(pmmoresult.findall('MO')) == 1:
            if pmmoresult.findall('MO')[0].find('DN') is not None:
                dn = pmmoresult.findall('MO')[0].find('DN').text
            elif pmmoresult.findall('MO')[0].find('localMoid') is not None:
                dn = pmmoresult.findall('MO')[0].find('localMoid').text
            else:
                raise KPIFailFormatXML('Not found DN or localMoid')
        else:
            dn = XMLParser.__format_dn(pmmoresult)
        return dn

    @staticmethod
    def __format_dn(pmmoresults):
        """

        :param pmmoresults:
        :return:
        """
        dn = pmmoresults.findall('MO')[0].find('DN').text
        for mo in pmmoresults.findall('MO')[1:]:
            dn_format = re.findall('PLMN-PLMN(.*)', mo.find('DN').text)[0]
            dn = '{}{}'.format(dn, dn_format)
        return dn


class HASHParser(ParserInterface):
    def __init__(self, path_file, counters_need):
        """

        :param path_file:
        :param counters_need:
        """
        super(HASHParser, self).__init__(path_file, counters_need)

    def parse(self):
        """

        :return:
        """
        file_hash = retrieve(self._path_file)
        for test in file_hash['-STATS']:
            for dn in file_hash['-STATS'][test]:
                self._ParserInterface__add_parameters(file_hash, test, dn)

    def _ParserInterface__add_parameters(self, file_hash, test, dn):
        """

        :param file_hash:
        :param test:
        :param dn:
        :return:
        """
        key = list(file_hash['-STATS'][test][dn]['-LEGEND'])[0]
        start_time = file_hash['-STATS'][test][dn]['-LEGEND'][key]['-RAW']
        if start_time not in self._measurements_file:
            self._measurements_file[start_time] = PMMeasurement(start_time)
        for m_parameter in file_hash['-STATS'][test][dn]['-COUNTER']:
            if self._counters_need == 'all' or m_parameter in self._counters_need:
                self._measurements_file[start_time].add_counter_to_measurement_type(test, m_parameter)
                self._measurements_file[start_time].add_parameters_pmmeasurement(
                    m_parameter, file_hash['-STATS'][test][dn]['-COUNTER'][m_parameter]['-VAL'][0], dn)


class RTPMParser(ParserInterface):

    def __init__(self, path_file, counters_need):
        """

        :param path_file:
        :param counters_need:
        """
        super(RTPMParser, self).__init__(path_file, counters_need)

    def parse(self):
        """

        :return:
        """
        file_rtpm = open(self._path_file)
        file_rtpm_str = file_rtpm.read()
        file_rtpm_str = re.sub(r'\n', '', file_rtpm_str)
        parse_ts = re.findall(r'"TS" => ({.*)\);', file_rtpm_str)[0]
        parse_ts = re.sub(r'=>', ':', parse_ts)
        parse_dict_ts = eval(parse_ts)

        parse_dn = re.findall(r'"DN" => ({.*),  "TS"', file_rtpm_str)[0]
        parse_dn = re.sub(r'=>', ':', parse_dn)
        parse_dict_dn = eval(parse_dn)

        start_time = parse_dict_ts['1']
        interval = len(parse_dict_ts)

        if start_time not in self._measurements_file:
            self._measurements_file[start_time] = PMMeasurement(start_time, interval)

        self._ParserInterface__add_parameters(parse_dict_dn, start_time)

    def _ParserInterface__add_parameters(self, parse_dict_dn, start_time):
        """

        :param parse_dict_dn:
        :param start_time:
        :return:
        """
        for dn in parse_dict_dn:
            for m_number in parse_dict_dn[dn]:
                for m_parameter in parse_dict_dn[dn][m_number]['COUNTERS']:
                    if self._counters_need == 'all' or m_parameter in self._counters_need:
                        self._measurements_file[start_time].add_counter_to_measurement_type('{}({})'.format(
                            parse_dict_dn[dn][m_number]['MEAS_TYPE'], m_number), m_parameter)
                        self._measurements_file[start_time].add_parameters_pmmeasurement(
                            m_parameter, parse_dict_dn[dn][m_number]['COUNTERS'][m_parameter]['VALUE'], dn)
